def maxLengthUnique(arr: list[str]) -> int:
    valid = [s for s in arr if len(set(s)) == len(s)]
    res = 0
    def backtrack(idx, curr_set):
        nonlocal res
        res = max(res, len(curr_set))
        for i in range(idx, len(valid)):
            s_set = set(valid[i])
            if not (curr_set & s_set):
                backtrack(i + 1, curr_set | s_set)
    backtrack(0, set())
    return res

